# ER-301 (stolmine) UI planning domain -- EMPIRICAL CRAWL MAP.
#
# GENERATED by tools/ui_crawl.py [stol:ui-planner-crawler]; do NOT hand-edit.
# Re-crawl + gate with `scripts/dev ui-crawl` (STOL_UPDATE_UI_CRAWL=1 accepts a
# vetted change). Crawling drives the headless emu and is SLOW -- it is a manual
# / CI gate ONLY, never on the commit path. Deterministic: seeded emu, sorted
# output, byte-identical on an unchanged build.
#
# [[transition]]  pre-fluents --[gesture]--> post-fluents (added/removed delta),
#                 keyed by fluent hash; single-gesture BFS observations.
# [[state]]       the fluent set behind each hash.
# [[resolved]]    the 6 needs_crawl operators (ui-operators.toml) resolved to a
#                 precondition RULE + gesture SKELETON with driven proofs. The
#                 solver consumes these alongside the static ui-operators.toml.
# --------------------------------------------------------------------------------

[meta]
schema = 1
generator = "tools/ui_crawl.py"
seeds = ["boot", "linked12", "sequencer", "unit_inserted"]
states = 24
transitions = 185
resolved = 7

[bounds]
max_depth = 3
max_states = 24
settle_frames = 20
encoder_detents = 3
unrestricted_nodes = ["home", "scope", "sequencer", "unit_picker_dense"]
# denylisted (never probed): destructive / irreversible gestures.
deny_global = ["storage_down"]
deny_home_header_commands = ["sub1", "sub2", "sub3"]

[bounds.safe_restricted]  # screen -> only these candidates probed
admin = ["cancel", "main2", "storage_up"]
hold = ["cancel", "mode_center"]
