[[resolved]]
id = "build_selection"
precondition = ["context(sequencer)", "~modal(selectionActive)"]
gesture = ["down SHIFT", "turn 3", "up SHIFT", "frames 6"]
effect = ["modal(selectionActive)"]
rule = "Nav-mode shift+encoder (SHIFT held, encoder turned) on the grid sequencer builds a row-range selection on the focused column: GridView:encoder shifted branch sets self.selectionActive=true. The flag INITIALIZES false, so modal(selectionActive) is a clean ABSENT->PRESENT boundary (unlike the always-truthy markingMode idle-string quirk in UI_STATE_SCHEMA.md). DURABLE: it persists past `up SHIFT` until UP/CANCEL/column-change. Non-destructive (a highlighted range; the bulk-edit nudge is a later gesture)."
proof = "{modal_added=true; post=86863aa309f5; pre=dbea93790541; selection_after=true; selection_before=false; selection_durable=true}"

[[resolved]]
id = "collapse"
precondition = ["context(home)", "focused_unit(u)", "expanded view"]
gesture = ["press {u_header_main}", "frames 8", "press ENTER", "frames 15"]
effect = ["slot_control map -> u.views.collapsed (unit-specific)"]
rule = "Press u's header MAIN column to focus its header spot, then ENTER (Unit.Base.Header:enterReleased) toggles currentViewName collapsed<->expanded. {u_header_main} = the live MAIN slot whose control is Unit.Base.Header. The resulting slot_control map is u-specific: manifest units[u].views.expanded / .collapsed."
proof = "{collapsed_slots=[slot_control(M1,ChainTitleControl),slot_control(M2,1),slot_control(M2,InputControl),slot_control(M3,Test Osc),slot_control(M3,Unit.Base.Header),slot_control(M4,MonitorControl)]; expanded_slots=[slot_control(M1,Test Osc),slot_control(M1,Unit.Base.Header),slot_control(M2,Unit.ViewControl.Pitch),slot_control(M2,V/oct),slot_control(M3,Unit.ViewControl.GainBias),slot_control(M3,f0),slot_control(M4,Unit.ViewControl.GainBias),slot_control(M4,phase),slot_control(M5,Unit.ViewControl.GainBias),slot_control(M5,fdbk),slot_control(M6,Unit.ViewControl.Gate),slot_control(M6,sync)]; from_view=expanded; to_view=collapsed}"

[[resolved]]
id = "expand"
precondition = ["context(home)", "focused_unit(u)", "collapsed view"]
gesture = ["press {u_header_main}", "frames 8", "press ENTER", "frames 15"]
effect = ["slot_control map -> u.views.expanded (unit-specific)"]
rule = "Press u's header MAIN column to focus its header spot, then ENTER (Unit.Base.Header:enterReleased) toggles currentViewName collapsed<->expanded. {u_header_main} = the live MAIN slot whose control is Unit.Base.Header. The resulting slot_control map is u-specific: manifest units[u].views.expanded / .collapsed."
proof = "{expanded_slots=[slot_control(M1,Test Osc),slot_control(M1,Unit.Base.Header),slot_control(M2,Unit.ViewControl.Pitch),slot_control(M2,V/oct),slot_control(M3,Unit.ViewControl.GainBias),slot_control(M3,f0),slot_control(M4,Unit.ViewControl.GainBias),slot_control(M4,phase),slot_control(M5,Unit.ViewControl.GainBias),slot_control(M5,fdbk),slot_control(M6,Unit.ViewControl.Gate),slot_control(M6,sync)]; from_view=collapsed; to_view=expanded}"

[[resolved]]
id = "focus_unit"
precondition = ["context(home)", "unit_in_chain(u)"]
gesture = ["turn {N}", "frames 6"]
effect = ["focused_unit(u)"]
rule = "N = signed detents (3 raw/step) to move the chain SpottedStrip section cursor to u; the count depends on u's live position in the chain and the current cursor. focused_unit(u) holds iff the section cursor sits on u's Unit section (selectionSectionClass=='Unit'); landing on u is what insert does (auto-focus, proof below)."
proof = "{focused_unit_holds=true; selection_class=Unit; state=91f87da673d6; unit=Test Osc #1}"

[[resolved]]
id = "insert"
precondition = ["context(unit_picker_dense)"]
gesture = ["turn {3*row}", "frames 6", "press {MAIN1=left|MAIN4=right}", "frames 30"]
effect = ["unit_in_chain(u)", "focused_unit(u)", "context(home)"]
rule = "The picker is a 2-column channel-count-filtered sorted list (read live from window.rows). row = target row index (0-based); N = 3 raw detents/row (EncoderThreshold.Default); pick MAIN1 for the left cell, MAIN4 for the right. Lands home, unit focused+expanded."
proof = "{picked=row 1 right (turn 3, MAIN4); picker_rows=0:Custom Effect|Custom Source ; 1:Mix|Test Osc; post=91f87da673d6; pre=4ff1653cc841; title=Test Osc #1; view=expanded}"

[[resolved]]
id = "open_picker"
precondition = ["context(home)", "slot_control(M{i},EmptySection.EmptyControl)"]
gesture = ["press MAIN{i}", "frames 15"]
effect = ["context(unit_picker_dense)"]
rule = "i = the MAIN slot index whose control is EmptySection.EmptyControl (M3 on a mono chain; M4 after a stereo link adds a second input spot)."
proof = "{case=mono; empty_slot=M3; opened=true; post=4ff1653cc841; pre=8576c81eefe8} {case=linked; empty_slot=M4; opened=true; post=888c7cae6bc7; pre=765373d25444}"

[[resolved]]
id = "set_cell"
precondition = ["context(sequencer)", "column_cursor(col)"]
gesture = ["press ENTER", "turn {nudges}", "frames 6"]
effect = ["modal(editingL1)", "cell(slot,col,row,v)"]
rule = "Enter L1 edit with ENTER (modal editingL1), then encoder-nudge to v. The row is reached by scrolling focusHead in nav mode first. The value is ARITHMETIC, not crawled: v = f(nudges) with a per-column step (SEQUENCER.md); e.g. the tr/transpose column steps 1.0 per encoder threshold (turn 3), so one nudge takes 0 -> 1.0."
proof = "{after=6b0cf03a6c9e; col_hash=d640e21ae43f; editing_modal=true; pre=dbea93790541; value_after_one_nudge=1.0000; value_before=0.0000}"
